def solve(WELL_FORMED):
    chain = []
    for w in WELL_FORMED:
        if len(chain) == 0:
            chain.append(w)
        else:
            last = chain[-1]
            if last == 'a':
                chain.append(w)
            else:
                chain.append(w)
                chain.append(last)
    return chain

def chain_to_string(chain):
    return ', '.join(chain)

